// n8n Code 节点：Build LLM Request Body
// 读取 /config/glm_script_prompt_config.jsonc 中的 GLM 提示词配置。

const fs = require('fs');
const item = $input.first().json;
const configPath = $env.GLM_SCRIPT_PROMPT_CONFIG_PATH || '/config/glm_script_prompt_config.jsonc';

const fallbackConfig = {
  model: 'glm-5.1',
  temperature: 0.7,
  max_tokens: 8000,
  system_prompt: '你是一个专业短视频编导、内容运营和平台风控助手。你的任务是生成可执行的短视频脚本包。必须只输出严格 JSON。',
  user_prompt_template: '请根据选题生成短视频脚本包。\n选题：{{topic}}\n平台：{{platform}}\n风格：{{style}}\n目标时长：{{duration_seconds}} 秒\n语言：{{language}}\n目标用户：{{target_audience}}\n必须输出严格 JSON，包含 title、hook、script、cover_text、template_type、hashtags、shots、risk_check。'
};

function stripJsonComments(text) {
  return String(text || '')
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .replace(/(^|[^:])\/\/.*$/gm, '$1');
}

function readPromptConfig() {
  try {
    if (!fs.existsSync(configPath)) return fallbackConfig;
    const data = JSON.parse(stripJsonComments(fs.readFileSync(configPath, 'utf8')));
    return { ...fallbackConfig, ...data };
  } catch (error) {
    throw new Error('读取 GLM 提示词配置失败：' + configPath + '；' + error.message);
  }
}

function renderTemplate(template, values) {
  return String(template || '').replace(/{{\s*([a-zA-Z0-9_]+)\s*}}/g, (_, key) => {
    const value = values[key];
    return value === undefined || value === null || value === '' ? '' : String(value);
  });
}

const values = {
  topic: item.topic,
  platform: item.platform,
  style: item.style,
  duration_seconds: item.duration_seconds,
  language: item.language || 'zh-CN',
  target_audience: item.target_audience || '普通短视频用户'
};
const promptConfig = readPromptConfig();
const systemPrompt = renderTemplate(promptConfig.system_prompt, values);
const userPrompt = renderTemplate(promptConfig.user_prompt_template, values);

return [
  {
    json: {
      ...item,
      prompt_config_path: configPath,
      llm_request_body: {
        model: promptConfig.model || 'glm-5.1',
        temperature: promptConfig.temperature ?? 0.7,
        max_tokens: promptConfig.max_tokens ?? 8000,
        response_format: { type: 'json_object' },
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: userPrompt }
        ]
      }
    }
  }
];

// n8n Code 节点：Parse LLM Response
// 作用：兼容 OpenAI-compatible HTTP Response / n8n AI 节点的常见输出格式，解析 JSON，并整理成 Postgres 更新字段。

function extractText(json) {
  if (!json || typeof json !== 'object') return '';

  // 如果 HTTP Request 使用了 “Put Response in Field = llm_response”
  if (json.llm_response?.choices?.[0]?.message?.content) {
    return json.llm_response.choices[0].message.content;
  }

  // OpenAI-compatible 原始响应
  if (json.choices?.[0]?.message?.content) {
    return json.choices[0].message.content;
  }

  // 一些 n8n AI / LLM 节点常见字段
  if (typeof json.output === 'string') return json.output;
  if (typeof json.text === 'string') return json.text;
  if (typeof json.response === 'string') return json.response;
  if (typeof json.message?.content === 'string') return json.message.content;

  // 万不得已：尝试把整个对象当作文本解析
  return JSON.stringify(json);
}

function cleanJsonText(text) {
  let s = String(text || '').trim();
  s = s.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();

  // 如果模型输出前后有废话，截取第一个 { 到最后一个 }
  const start = s.indexOf('{');
  const end = s.lastIndexOf('}');
  if (start >= 0 && end > start) {
    s = s.slice(start, end + 1);
  }
  return s;
}

const input = $input.first().json;
const source = $('Postgres - Mark GENERATING_SCRIPT').first().json;
const raw = extractText(input);
const cleaned = cleanJsonText(raw);

let data;
try {
  data = JSON.parse(cleaned);
} catch (err) {
  throw new Error(`LLM 输出不是合法 JSON：${err.message}\n原始输出：${raw.slice(0, 1000)}`);
}

const hashtags = Array.isArray(data.hashtags) ? data.hashtags : [];
const shots = Array.isArray(data.shots) ? data.shots : [];
const templateType = ['knowledge', 'list', 'contrast', 'story'].includes(data.template_type) ? data.template_type : 'knowledge';
const riskCheck = data.risk_check && typeof data.risk_check === 'object' ? data.risk_check : {};

return [
  {
    json: {
      id: source.id,
      topic: source.topic,
      platform: source.platform,
      style: source.style,
      duration_seconds: source.duration_seconds,
      title: data.title || '',
      hook: data.hook || '',
      script: data.script || '',
      cover_text: data.cover_text || '',
      hashtags,
      hashtags_json: JSON.stringify(hashtags),
      shots,
      shots_json: JSON.stringify(shots),
      template_type: templateType,
      risk_check: riskCheck,
      risk_check_json: JSON.stringify(riskCheck),
      status: 'SCRIPT_READY',
      updated_at: new Date().toISOString()
    }
  }
];
